class Solution {
    public String abbreviateProduct(int left, int right) {
        int c2 = 0, c5 = 0;
        long small = 1;
        boolean big = false;
        long suffix = 1;
        final long MOD = 100000L;
        final long LIMIT = 10000000000L;
        double logSum = 0;
        for (int i = left; i <= right; i++) {
            int x = i;
            while (x % 2 == 0) { x /= 2; c2++; }
            while (x % 5 == 0) { x /= 5; c5++; }
            suffix = (suffix * x) % MOD;
            if (!big) {
                small *= x;
                if (small > LIMIT) big = true;
            }
            logSum += Math.log10((double) i);
        }
        int m = Math.min(c2, c5);
        int a = c2 - m, b = c5 - m;
        if (!big) {
            for (int k = 0; k < a && !big; k++) {
                small *= 2;
                if (small > LIMIT) big = true;
            }
            for (int k = 0; k < b && !big; k++) {
                small *= 5;
                if (small > LIMIT) big = true;
            }
            if (!big) {
                return small + "e" + m;
            }
        }
        for (int k = 0; k < a; k++) suffix = (suffix * 2) % MOD;
        for (int k = 0; k < b; k++) suffix = (suffix * 5) % MOD;
        double frac = logSum - Math.floor(logSum);
        long prefix = (long) Math.floor(Math.pow(10, frac) * 10000 + 1e-9);
        if (prefix >= 100000) prefix = 99999;
        if (prefix < 10000) prefix = 10000;
        StringBuilder sb = new StringBuilder();
        sb.append(prefix);
        sb.append("...");
        String suf = String.valueOf(suffix);
        while (suf.length() < 5) suf = "0" + suf;
        sb.append(suf);
        sb.append("e").append(m);
        return sb.toString();
    }
}
