Use iterative DFS with coloring (0 = unvisited, 1 = visiting, 2 = safe) to detect nodes that can reach a cycle; alternatively reverse-graph topological sort. Here I'll use the coloring approach with an explicit stack to avoid recursion depth issues.

```java
import java.util.*;

class Solution {
    public List<Integer> eventualSafeNodes(int[][] graph) {
        int n = graph.length;
        int[] color = new int[n]; // 0 = unvisited, 1 = visiting, 2 = safe, 3 = unsafe
        List<Integer> result = new ArrayList<>();
        for (int s = 0; s < n; s++) {
            if (color[s] != 0) continue;
            // iterative DFS
            Deque<int[]> stack = new ArrayDeque<>(); // {node, next edge index}
            color[s] = 1;
            stack.push(new int[]{s, 0});
            while (!stack.isEmpty()) {
                int[] top = stack.peek();
                int u = top[0];
                if (color[u] == 3) {
                    stack.pop();
                    continue;
                }
                if (top[1] < graph[u].length) {
                    int v = graph[u][top[1]++];
                    if (color[v] == 0) {
                        color[v] = 1;
                        stack.push(new int[]{v, 0});
                    } else if (color[v] == 1 || color[v] == 3) {
                        // reaches a cycle or unsafe node: mark u unsafe
                        color[u] = 3;
                        stack.pop();
                    }
                    // color[v] == 2: safe, continue
                } else {
                    color[u] = 2;
                    stack.pop();
                }
            }
        }
        // Nodes marked unsafe may have been visited but their ancestors still on the stack
        // were handled correctly: when an ancestor later encounters a child with color 3, it becomes 3.
        // However, ancestors that already passed the child before it became 3 are impossible
        // since a child is fully processed before the parent continues.
        for (int i = 0; i < n; i++) {
            if (color[i] == 2) result.add(i);
        }
        return result;
    }
}
