import java.util.*;

class Solution {
    public long maximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        int n = flowers.length;
        long[] f = new long[n];
        for (int i = 0; i < n; i++) f[i] = Math.min(flowers[i], target);
        Arrays.sort(f);
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + f[i];
        long best = 0;
        long costComplete = 0;
        for (int i = n; i >= 0; i--) {
            if (i < n) costComplete += target - f[i];
            if (costComplete > newFlowers) break;
            long remaining = newFlowers - costComplete;
            long beauty = (long) (n - i) * full;
            if (i > 0) {
                long lo = f[0], hi = target - 1;
                while (lo < hi) {
                    long mid = lo + (hi - lo + 1) / 2;
                    int l = 0, r = i;
                    while (l < r) {
                        int m = (l + r) >>> 1;
                        if (f[m] < mid) l = m + 1; else r = m;
                    }
                    int cnt = l;
                    long cost = mid * cnt - prefix[cnt];
                    if (cost <= remaining) lo = mid; else hi = mid - 1;
                }
                beauty += lo * partial;
            }
            best = Math.max(best, beauty);
        }
        return best;
    }
}
