class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> res = new ArrayList<>();
        String digits = s.substring(1, s.length() - 1);
        int n = digits.length();
        for (int i = 1; i < n; i++) {
            List<String> left = gen(digits.substring(0, i));
            List<String> right = gen(digits.substring(i));
            for (String l : left) {
                for (String r : right) {
                    res.add("(" + l + ", " + r + ")");
                }
            }
        }
        return res;
    }

    private List<String> gen(String t) {
        List<String> list = new ArrayList<>();
        int n = t.length();
        if (n == 1) {
            list.add(t);
            return list;
        }
        boolean leadingZero = t.charAt(0) == '0';
        boolean trailingZero = t.charAt(n - 1) == '0';
        if (leadingZero && trailingZero) {
            return list;
        }
        if (leadingZero) {
            list.add("0." + t.substring(1));
            return list;
        }
        if (trailingZero) {
            list.add(t);
            return list;
        }
        list.add(t);
        for (int i = 1; i < n; i++) {
            list.add(t.substring(0, i) + "." + t.substring(i));
        }
        return list;
    }
}
