class Solution {
    public double average(int[] salary) {
        long sum = 0;
        int min = Integer.MAX_VALUE;
        int max = Integer.MIN_VALUE;
        for (int s : salary) {
            sum += s;
            if (s < min) min = s;
            if (s > max) max = s;
        }
        sum -= min;
        sum -= max;
        return (double) sum / (salary.length - 2);
    }
}
