Sort the array, then use DP: for each value, count trees rooted at it as 1 plus, for every pair of factors (a, b) with a*b = value both in the array, dp[a]*dp[b]. Using a hash map for lookup gives O(n²).

```java
import java.util.*;

class Solution {
    public int numFactoredBinaryTrees(int[] arr) {
        final long MOD = 1_000_000_007L;
        Arrays.sort(arr);
        int n = arr.length;
        long[] dp = new long[n];
        Map<Integer, Integer> idx = new HashMap<>();
        long total = 0;
        for (int i = 0; i < n; i++) {
            dp[i] = 1;
            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] == 0) {
                    int other = arr[i] / arr[j];
                    Integer k = idx.get(other);
                    if (k != null) {
                        dp[i] = (dp[i] + dp[j] * dp[k]) % MOD;
                    }
                }
            }
            idx.put(arr[i], i);
            total = (total + dp[i]) % MOD;
        }
        return (int) total;
    }
}
