Classic reverse union-find approach: remove all hit bricks, union the remaining, then add hits back in reverse order and measure the growth of the component connected to the virtual roof.

```java
class Solution {
    private int[] parent;
    private int[] size;

    private int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        size[ra] += size[rb];
    }

    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length, n = grid[0].length;
        int[][] g = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                g[i][j] = grid[i][j];
            }
        }
        for (int[] h : hits) {
            if (g[h[0]][h[1]] == 1) g[h[0]][h[1]] = 2; // mark hit brick
        }
        int roof = m * n;
        parent = new int[m * n + 1];
        size = new int[m * n + 1];
        for (int i = 0; i <= m * n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (g[i][j] == 1) {
                    int id = i * n + j;
                    if (i == 0) union(id, roof);
                    for (int d = 0; d < 4; d++) {
                        int ni = i + dr[d], nj = j + dc[d];
                        if (ni >= 0 && ni < m && nj >= 0 && nj < n && g[ni][nj] == 1) {
                            union(id, ni * n + nj);
                        }
                    }
                }
            }
        }
        int[] res = new int[hits.length];
        for (int k = hits.length - 1; k >= 0; k--) {
            int r = hits[k][0], c = hits[k][1];
            if (g[r][c] != 2) {
                res[k] = 0;
                continue;
            }
            int before = size[find(roof)];
            g[r][c] = 1;
            int id = r * n + c;
            if (r == 0) union(id, roof);
            for (int d = 0; d < 4; d++) {
                int ni = r + dr[d], nj = c + dc[d];
                if (ni >= 0 && ni < m && nj >= 0 && nj < n && g[ni][nj] == 1) {
                    union(id, ni * n + nj);
                }
            }
            int after = size[find(roof)];
            res[k] = Math.max(0, after - before - 1);
        }
        return res;
    }
}
