class Solution {
    public int countMaxOrSubsets(int[] nums) {
        int n = nums.length;
        int maxOr = 0;
        for (int x : nums) maxOr |= x;
        int total = 1 << n;
        int[] dp = new int[total];
        int count = 0;
        for (int mask = 1; mask < total; mask++) {
            int low = mask & (-mask);
            int idx = Integer.numberOfTrailingZeros(low);
            dp[mask] = dp[mask ^ low] | nums[idx];
            if (dp[mask] == maxOr) count++;
        }
        return count;
    }
}
