class Solution {
    public int countVowelSubstrings(String word) {
        int n = word.length();
        int count = 0;
        for (int i = 0; i < n; i++) {
            int mask = 0;
            for (int j = i; j < n; j++) {
                char c = word.charAt(j);
                int bit;
                switch (c) {
                    case 'a': bit = 1; break;
                    case 'e': bit = 2; break;
                    case 'i': bit = 4; break;
                    case 'o': bit = 8; break;
                    case 'u': bit = 16; break;
                    default: bit = -1;
                }
                if (bit == -1) break;
                mask |= bit;
                if (mask == 31) count++;
            }
        }
        return count;
    }
}
