class MKAverage {
    private int m, k;
    private static final int N = 100001;
    private long[] cntTree = new long[N + 1];
    private long[] sumTree = new long[N + 1];
    private java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
    private int LOG;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
        LOG = 1;
        while ((1 << LOG) <= N) LOG++;
    }

    private void update(int idx, long dc, long ds) {
        for (int i = idx; i <= N; i += i & (-i)) {
            cntTree[i] += dc;
            sumTree[i] += ds;
        }
    }

    // sum of the smallest t elements
    private long sumSmallest(int t) {
        if (t <= 0) return 0;
        int pos = 0;
        long cnt = 0, sum = 0;
        for (int b = LOG; b >= 0; b--) {
            int next = pos + (1 << b);
            if (next <= N && cnt + cntTree[next] < t) {
                pos = next;
                cnt += cntTree[next];
                sum += sumTree[next];
            }
        }
        // pos+1 is the value where the t-th element lies
        int v = pos + 1;
        sum += (t - cnt) * (long) v;
        return sum;
    }

    public void addElement(int num) {
        queue.addLast(num);
        update(num, 1, num);
        if (queue.size() > m) {
            int old = queue.pollFirst();
            update(old, -1, -old);
        }
    }

    public int calculateMKAverage() {
        if (queue.size() < m) return -1;
        long total = sumSmallest(m - k) - sumSmallest(k);
        return (int) (total / (m - 2 * k));
    }
}

