Classic DP: for each stone index i, track the set of jump sizes k that can land there. Since max jump to reach stone i is at most i, we can use a boolean table dp[i][k] of size n×(n+1).

```java
import java.util.*;

class Solution {
    public boolean canCross(int[] stones) {
        int n = stones.length;
        if (n >= 2 && stones[1] != 1) return false;
        Map<Long, Integer> idx = new HashMap<>();
        for (int i = 0; i < n; i++) idx.put((long) stones[i], i);
        boolean[][] dp = new boolean[n][n + 2];
        dp[0][0] = true;
        for (int i = 0; i < n; i++) {
            for (int k = 0; k <= n; k++) {
                if (!dp[i][k]) continue;
                for (int d = k - 1; d <= k + 1; d++) {
                    if (d <= 0) continue;
                    long target = (long) stones[i] + d;
                    Integer j = idx.get(target);
                    if (j != null && j > i && d <= n) {
                        dp[j][d] = true;
                    }
                }
            }
        }
        for (int k = 0; k <= n + 1; k++) {
            if (dp[n - 1][k]) return true;
        }
        return false;
    }
}
```

