class Solution {
    public int maxScore(int[] nums) {
        int m = nums.length;
        int[][] g = new int[m][m];
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                g[i][j] = gcd(nums[i], nums[j]);
            }
        }
        int full = 1 << m;
        int[] dp = new int[full];
        for (int mask = 0; mask < full; mask++) {
            int cnt = Integer.bitCount(mask);
            if ((cnt & 1) != 0) continue;
