class Solution {
    public int maximumANDSum(int[] nums, int numSlots) {
        int n = nums.length;
        int total = 1;
        for (int i = 0; i < numSlots; i++) total *= 3;
        int[] dp = new int[total];
        int best = 0;
        for (int state = 0; state < total; state++) {
            int cnt = 0;
            int s = state;
            for (int i = 0; i < numSlots; i++) {
                cnt += s % 3;
                s /= 3;
            }
            if (cnt >= n) {
                best = Math.max(best, dp[state]);
                continue;
            }
            int pw = 1;
            s = state;
            for (int i = 0; i < numSlots; i++) {
                int d = s % 3;
                if (d < 2) {
                    int next = state + pw;
                    int val = dp[state] + (nums[cnt] & (i + 1));
                    if (val > dp[next]) dp[next] = val;
                }
                s /= 3;
                pw *= 3;
            }
        }
        return best;
    }
}
