class Solution {
    public String maximumBinaryString(String binary) {
        int n = binary.length();
        int firstZero = -1;
        int zeros = 0;
        for (int i = 0; i < n; i++) {
            if (binary.charAt(i) == '0') {
                if (firstZero == -1) firstZero = i;
                zeros++;
            }
        }
        if (zeros <= 1) return binary;
        char[] res = new char[n];
        for (int i = 0; i < n; i++) res[i] = '1';
        res[firstZero + zeros - 1] = '0';
        return new String(res);
    }
}
