Standard approach: track count of each number, and count of counts (freq[f] = how many distinct numbers have frequency f), plus the max frequency. For each prefix of length i+1, it's valid if:
- maxF == 1 (all distinct, remove any), or
- freq[maxF] * maxF == i (all elements except one have maxF, and that one has frequency 1), or
- freq[maxF] == 1 and (maxF-1) * (freq[maxF-1] + 1) == i (one number has one extra occurrence).

```java
class Solution {
    public int maxEqualFreq(int[] nums) {
        int n = nums.length;
        int[] cnt = new int[100001];
        int[] freq = new int[n + 2];
        int maxF = 0;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            if (cnt[x] > 0) {
                freq[cnt[x]]--;
            }
            cnt[x]++;
            freq[cnt[x]]++;
            if (cnt[x] > maxF) {
                maxF = cnt[x];
            }
            int len = i + 1;
            if (maxF == 1) {
                ans = len;
            } else if ((long) freq[maxF] * maxF == len - 1) {
                ans = len;
            } else if (freq[maxF] == 1 && (long) (maxF - 1) * (freq[maxF - 1] + 1) == len - 1) {
                ans = len;
            }
        }
        return ans;
    }
}
