class Solution {
    public long maxRunTime(int n, int[] batteries) {
        long total = 0;
        for (int b : batteries) total += b;
        long lo = 1, hi = total / n;
        while (lo < hi) {
            long mid = lo + (hi - lo + 1) / 2;
            long sum = 0;
            for (int b : batteries) sum += Math.min((long) b, mid);
            if (sum >= mid * n) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }
}
