Standard bitmask DP over rows: for each row, enumerate masks that fit valid seats and have no adjacent bits; transition from previous row masks where no diagonal conflicts exist.

```java
class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length, n = seats[0].length;
        int[] valid = new int[m];
        for (int i = 0; i < m; i++) {
            int mask = 0;
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') mask |= (1 << j);
            }
            valid[i] = mask;
        }
        int full = 1 << n;
        int[] prev = new int[full];
        java.util.Arrays.fill(prev, -1);
        prev[0] = 0;
        for (int i = 0; i < m; i++) {
            int[] cur = new int[full];
            java.util.Arrays.fill(cur, -1);
            for (int mask = 0; mask < full; mask++) {
                if ((mask & valid[i]) != mask) continue;
                if ((mask & (mask << 1)) != 0) continue;
                int cnt = Integer.bitCount(mask);
                for (int pm = 0; pm < full; pm++) {
                    if (prev[pm] < 0) continue;
                    if ((pm & (mask << 1)) != 0) continue;
                    if ((pm & (mask >> 1)) != 0) continue;
                    int val = prev[pm] + cnt;
                    if (val > cur[mask]) cur[mask] = val;
                }
            }
            prev = cur;
        }
        int best = 0;
        for (int v : prev) best = Math.max(best, v);
        return best;
    }
}
