```java
import java.util.*;

class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        Arrays.sort(initial);
        int best = -1;
        int bestCount = Integer.MAX_VALUE;
        for (int removed : initial) {
            boolean[] visited = new boolean[n];
            visited[removed] = true;
            Deque<Integer> queue = new ArrayDeque<>();
            int count = 0;
            for (int s : initial) {
                if (s == removed) continue;
                if (!visited[s]) {
                    visited[s] = true;
                    queue.add(s);
                    count++;
                }
            }
            while (!queue.isEmpty()) {
                int u = queue.poll();
                for (int v = 0; v < n; v++) {
                    if (graph[u][v] == 1 && !visited[v]) {
                        visited[v] = true;
                        count++;
                        queue.add(v);
                    }
                }
            }
            if (count < bestCount) {
                bestCount = count;
                best = removed;
            }
        }
        return best;
    }
}
```

