inference_trace:
Classic DP over time: `dp[t][v]` = min cost to reach city `v` in exactly `t` minutes. Iterate `t` from 1 to `maxTime`, relaxing over all edges. Answer is the min over `dp[t][n-1]`.

```java
class Solution {
    public int minCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.length;
        final int INF = Integer.MAX_VALUE / 2;
        int[][] dp = new int[maxTime + 1][n];
        for (int t = 0; t <= maxTime; t++) {
            java.util.Arrays.fill(dp[t], INF);
        }
        dp[0][0] = passingFees[0];
        for (int t = 1; t <= maxTime; t++) {
            for (int[] e : edges) {
                int u = e[0], v = e[1], w = e[2];
                if (w > t) continue;
                int prev = t - w;
                if (dp[prev][u] < INF) {
                    int c = dp[prev][u] + passingFees[v];
                    if (c < dp[t][v]) dp[t][v] = c;
                }
                if (dp[prev][v] < INF) {
                    int c = dp[prev][v] + passingFees[u];
                    if (c < dp[t][u]) dp[t][u] = c;
                }
            }
        }
        int ans = INF;
        for (int t = 0; t <= maxTime; t++) {
            if (dp[t][n - 1] < ans) ans = dp[t][n - 1];
        }
        return ans >= INF ? -1 : ans;
    }
}
```

