```java
class Solution {
    private int m, n;

    public int minDays(int[][] grid) {
        m = grid.length;
        n = grid[0].length;
        if (countIslands(grid) != 1) return 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    grid[i][j] = 0;
                    int c = countIslands(grid);
                    grid[i][j] = 1;
                    if (c != 1) return 1;
                }
            }
        }
        return 2;
    }

    private int countIslands(int[][] grid) {
        boolean[][] vis = new boolean[m][n];
        int count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && !vis[i][j]) {
                    count++;
                    if (count > 1) return count;
                    dfs(grid, vis, i, j);
                }
            }
        }
        return count;
    }

    private void dfs(int[][] grid, boolean[][] vis, int i, int j) {
        int[] stack = new int[m * n];
        int top = 0;
        stack[top++] = i * n + j;
        vis[i][j] = true;
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};
        while (top > 0) {
            int cur = stack[--top];
            int r = cur / n, c = cur % n;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1 && !vis[nr][nc]) {
                    vis[nr][nc] = true;
                    stack[top++] = nr * n + nc;
                }
            }
        }
    }
}
