        int maxNeg = 0;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '[') {
                balance++;
            } else {
                balance--;
                if (balance < maxNeg) {
                    maxNeg = balance;
                }
            }
        }
        int unmatched = -maxNeg;
        return (unmatched + 1) / 2;
    }
}
