Bitmask DP: for each mask, store (sessions, currentSessionTime) pair; add tasks one by one to the current session or start a new one.

```java
class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int full = 1 << n;
        int[] sess = new int[full];
        int[] rem = new int[full];
        java.util.Arrays.fill(sess, Integer.MAX_VALUE);
        sess[0] = 1;
        rem[0] = sessionTime;
        for (int mask = 0; mask < full; mask++) {
            if (sess[mask] == Integer.MAX_VALUE) continue;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                int nm = mask | (1 << i);
                int ns, nr;
                if (rem[mask] >= tasks[i]) {
                    ns = sess[mask];
                    nr = rem[mask] - tasks[i];
                } else {
                    ns = sess[mask] + 1;
                    nr = sessionTime - tasks[i];
                }
                if (ns < sess[nm] || (ns == sess[nm] && nr > rem[nm])) {
                    sess[nm] = ns;
                    rem[nm] = nr;
                }
            }
        }
        return sess[full - 1];
    }
}
