Classic approach: the number of orderings producing the same BST is computed recursively — for root with left subtree of size L and right subtree of size R, ways = C(L+R, L) * ways(left) * ways(right). Subtract 1 at the end for the original ordering. Use Pascal's triangle for binomials mod 1e9+7.

```java
import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;
    private long[][] comb;

    public int numOfWays(int[] nums) {
        int n = nums.length;
        comb = new long[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                comb[i][j] = (comb[i - 1][j - 1] + (j <= i - 1 ? comb[i - 1][j] : 0)) % MOD;
            }
        }
        List<Integer> list = new ArrayList<>();
        for (int x : nums) list.add(x);
        long res = count(list);
        res = (res - 1 + MOD) % MOD;
        return (int) res;
    }

    private long count(List<Integer> arr) {
        if (arr.size() <= 2) return 1;
        int root = arr.get(0);
        List<Integer> left = new ArrayList<>();
        List<Integer> right = new ArrayList<>();
        for (int i = 1; i < arr.size(); i++) {
            int v = arr.get(i);
            if (v < root) left.add(v);
            else right.add(v);
        }
        long l = count(left);
        long r = count(right);
        long total = comb[left.size() + right.size()][left.size()];
        total = total * l % MOD;
        total = total * r % MOD;
        return total;
    }
}
```

