Approach: count frequencies in each array. For each element `a` in one array, compute `a*a` (long), then for each distinct value `b` in the other array's frequency map, if `a*a % b == 0`, let `c = a*a / b`. If `c == b`, add `cnt[b]*(cnt[b]-1)/2`; if `c > b` and present, add `cnt[b]*cnt[c]`. Sum over both directions.

```java
import java.util.*;

class Solution {
    public int numTriplets(int[] nums1, int[] nums2) {
        return (int) (count(nums1, nums2) + count(nums2, nums1));
    }

    private long count(int[] a, int[] b) {
        Map<Long, Long> freq = new HashMap<>();
        for (int x : b) {
            freq.merge((long) x, 1L, Long::sum);
        }
        long total = 0;
        Map<Long, Long> aFreq = new HashMap<>();
        for (int x : a) {
            aFreq.merge((long) x, 1L, Long::sum);
        }
        for (Map.Entry<Long, Long> ae : aFreq.entrySet()) {
            long sq = ae.getKey() * ae.getKey();
            long ways = 0;
            for (Map.Entry<Long, Long> e : freq.entrySet()) {
                long v = e.getKey();
                if (sq % v != 0) continue;
                long c = sq / v;
                if (c == v) {
                    long cnt = e.getValue();
                    ways += cnt * (cnt - 1) / 2;
                } else if (c > v) {
                    Long cc = freq.get(c);
                    if (cc != null) {
                        ways += e.getValue() * cc;
                    }
                }
            }
            total += ways * ae.getValue();
        }
        return total;
    }
}
