Classic: choose n non-adjacent slices in a circular array maximizing sum. Solve linear version twice (excluding first or last element).

```java
class Solution {
    public int maxSizeSlices(int[] slices) {
        int m = slices.length;
        int n = m / 3;
        return Math.max(solve(slices, 0, m - 2, n), solve(slices, 1, m - 1, n));
    }

    private int solve(int[] s, int lo, int hi, int n) {
        int len = hi - lo + 1;
        if (len <= 0) return 0;
        // dp[i][j] = max sum picking j non-adjacent from first i elements
        int[][] dp = new int[len + 1][n + 1];
        for (int i = 1; i <= len; i++) {
            int val = s[lo + i - 1];
            for (int j = 0; j <= n; j++) {
                dp[i][j] = dp[i - 1][j];
                if (j > 0) {
                    int prev = (i >= 2) ? dp[i - 2][j - 1] : (j - 1 == 0 ? 0 : Integer.MIN_VALUE / 2);
                    if (i < 2 && j - 1 > 0) prev = Integer.MIN_VALUE / 2;
                    dp[i][j] = Math.max(dp[i][j], prev + val);
                }
            }
        }
        return dp[len][n];
    }
}
