import java.util.*;

class Solution {
    public List<String> removeInvalidParentheses(String s) {
        int left = 0, right = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                left++;
            } else if (c == ')') {
                if (left > 0) left--;
                else right++;
            }
        }
        List<String> res = new ArrayList<>();
        dfs(s, 0, left, right, 0, new StringBuilder(), res);
        return res;
    }

    private void dfs(String s, int idx, int left, int right, int open, StringBuilder sb, List<String> res) {
        if (open < 0) return;
        if (idx == s.length()) {
            if (left == 0 && right == 0 && open == 0) {
                res.add(sb.toString());
            }
            return;
        }
        char c = s.charAt(idx);
        int len = sb.length();
        if (c == '(') {
            // try removing this '(' only if it's the first in a run
            if (left > 0 && (idx == 0 || s.charAt(idx - 1) != '(' || len == 0 || sb.charAt(len - 1) != '(' || true)) {
                if (left > 0) {
                    // skip duplicates: remove only when previous char in s is not the same kept char
                    if (idx == 0 || s.charAt(idx - 1) != '(' || (len > 0 && sb.charAt(len - 1) != '(') || len == 0) {
                        dfs(s, idx + 1, left - 1, right, open, sb, res);
                    }
                }
            }
            sb.append(c);
            dfs(s, idx + 1, left, right, open + 1, sb, res);
            sb.setLength(len);
        } else if (c == ')') {
            if (right > 0) {
                if (idx == 0 || s.charAt(idx - 1) != ')' || (len > 0 && sb.charAt(len - 1) != ')') || len == 0) {
                    dfs(s, idx + 1, left, right - 1, open, sb, res);
                }
            }
            sb.append(c);
            dfs(s, idx + 1, left, right, open - 1, sb, res);
            sb.setLength(len);
        } else {
            sb.append(c);
            dfs(s, idx + 1, left, right, open, sb, res);
            sb.setLength(len);
        }
    }
}
