```java
class Solution {
    public int[] restoreArray(int[][] adjacentPairs) {
        final int OFFSET = 100000;
        final int SIZE = 200001;
        int[] a = new int[SIZE];
        int[] b = new int[SIZE];
        int[] cnt = new int[SIZE];
        for (int[] p : adjacentPairs) {
            int u = p[0] + OFFSET;
            int v = p[1] + OFFSET;
            if (cnt[u] == 0) a[u] = v; else b[u] = v;
            cnt[u]++;
            if (cnt[v] == 0) a[v] = u; else b[v] = u;
            cnt[v]++;
        }
        int n = adjacentPairs.length + 1;
        int start = -1;
        for (int[] p : adjacentPairs) {
            int u = p[0] + OFFSET;
            int v = p[1] + OFFSET;
            if (cnt[u] == 1) { start = u; break; }
            if (cnt[v] == 1) { start = v; break; }
        }
        int[] res = new int[n];
        int prev = -1;
        int cur = start;
        for (int i = 0; i < n; i++) {
            res[i] = cur - OFFSET;
            int next;
            if (cnt[cur] == 1) {
                next = a[cur];
            } else {
                next = (a[cur] == prev) ? b[cur] : a[cur];
            }
            prev = cur;
            cur = next;
        }
        return res;
    }
}
