Classic interval DP: dp[len][i][j] = whether s1[i..i+len) can be scrambled into s2[j..j+len). Try each split k; either no swap (left↔left, right↔right) or swap (left of s1 ↔ right of s2, right of s1 ↔ left of s2).

```java
class Solution {
    public boolean isScramble(String s1, String s2) {
        int n = s1.length();
        if (n != s2.length()) return false;
        if (s1.equals(s2)) return true;
        boolean[][][] dp = new boolean[n + 1][n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dp[1][i][j] = s1.charAt(i) == s2.charAt(j);
            }
        }
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len <= n; i++) {
                for (int j = 0; j + len <= n; j++) {
                    boolean ok = false;
                    for (int k = 1; k < len && !ok; k++) {
                        if (dp[k][i][j] && dp[len - k][i + k][j + k]) {
                            ok = true;
                        } else if (dp[k][i][j + len - k] && dp[len - k][i + k][j]) {
                            ok = true;
                        }
                    }
                    dp[len][i][j] = ok;
                }
            }
        }
        return dp[n][0][0];
    }
}
```

