            result.add(row);
        }
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int idx = i * n + j;
                int newIdx = (idx + k) % total;
                int ni = newIdx / n;
                int nj = newIdx % n;
                result.get(ni).set(nj, grid[i][j]);
            }
        }
        return result;
    }
}
