Use two TreeSets ordered by value (tie broken by index) so duplicates are handled cleanly; maintain a balanced split and read medians from the boundaries.

```java
import java.util.*;

class Solution {
    public double[] medianSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        Comparator<Integer> cmp = (a, b) -> {
            if (nums[a] != nums[b]) return Integer.compare(nums[a], nums[b]);
            return Integer.compare(a, b);
        };
        TreeSet<Integer> low = new TreeSet<>(cmp);   // smaller half, size = ceil(k/2)
        TreeSet<Integer> high = new TreeSet<>(cmp);  // larger half
        double[] res = new double[n - k + 1];

        for (int i = 0; i < n; i++) {
            // add index i
            if (low.isEmpty() || nums[i] <= nums[low.last()]) {
                low.add(i);
            } else {
                high.add(i);
            }
            // remove index i-k
            if (i >= k) {
                int rem = i - k;
                if (!low.remove(rem)) {
                    high.remove(rem);
                }
            }
            // rebalance
            while (low.size() > high.size() + 1) {
                high.add(low.pollLast());
            }
            while (high.size() > low.size()) {
                low.add(high.pollFirst());
            }
            if (i >= k - 1) {
                if ((k & 1) == 1) {
                    res[i - k + 1] = nums[low.last()];
                } else {
                    res[i - k + 1] = ((double) nums[low.last()] + (double) nums[high.first()]) / 2.0;
                }
            }
        }
        return res;
    }
}
