```java
class Solution {
    public int splitArray(int[] nums, int k) {
        long lo = 0, hi = 0;
        for (int x : nums) {
            lo = Math.max(lo, x);
            hi += x;
        }
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (canSplit(nums, k, mid)) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return (int) lo;
    }

    private boolean canSplit(int[] nums, int k, long limit) {
        int count = 1;
        long sum = 0;
        for (int x : nums) {
            if (sum + x > limit) {
                count++;
                sum = x;
                if (count > k) return false;
            } else {
                sum += x;
            }
        }
        return true;
    }
}
