Reversed trie approach: insert each word reversed into a trie, keep a buffer of the last up to 200 characters of the stream, and on each query walk the trie from the most recent character backwards.

```java
class StreamChecker {
    private static class Node {
        Node[] next = new Node[26];
        boolean end;
    }

    private final Node root = new Node();
    private final char[] buf = new char[200];
    private int pos = 0;
    private int size = 0;

    public StreamChecker(String[] words) {
        for (String w : words) {
            Node cur = root;
            for (int i = w.length() - 1; i >= 0; i--) {
                int c = w.charAt(i) - 'a';
                if (cur.next[c] == null) cur.next[c] = new Node();
                cur = cur.next[c];
            }
            cur.end = true;
        }
    }

    public boolean query(char letter) {
        buf[pos] = letter;
        pos = (pos + 1) % 200;
        if (size < 200) size++;
        Node cur = root;
        int idx = pos;
        for (int k = 0; k < size; k++) {
            idx = (idx - 1 + 200) % 200;
            int c = buf[idx] - 'a';
            cur = cur.next[c];
            if (cur == null) return false;
            if (cur.end) return true;
        }
        return false;
    }
}

