inference_trace:
Greedy: at each step, append the letter with the larger remaining count unless the last two characters are already that letter, in which case append the other.

```java
class Solution {
    public String strWithout3a3b(int a, int b) {
        StringBuilder sb = new StringBuilder();
        while (a > 0 || b > 0) {
            int n = sb.length();
            boolean lastTwoA = n >= 2 && sb.charAt(n - 1) == 'a' && sb.charAt(n - 2) == 'a';
            boolean lastTwoB = n >= 2 && sb.charAt(n - 1) == 'b' && sb.charAt(n - 2) == 'b';
            boolean writeA;
            if (lastTwoA) {
                writeA = false;
            } else if (lastTwoB) {
                writeA = true;
            } else {
                writeA = a >= b;
            }
            if (writeA) {
                if (a == 0) {
                    break;
                }
                sb.append('a');
                a--;
            } else {
                if (b == 0) {
                    break;
                }
                sb.append('b');
                b--;
            }
        }
        return sb.toString();
    }
}
