class Solution {
    private int[][][][] memo;

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memo = new int[n + 1][n + 1][n + 1][];
        return dp(n, firstPlayer, secondPlayer);
    }

    private int[] dp(int n, int l, int r) {
        if (l + r == n + 1) return new int[]{1, 1};
        if (l + r > n + 1) {
            int nl = n + 1 - r;
            int nr = n + 1 - l;
            l = nl;
            r = nr;
        }
        if (memo[n][l][r] != null) return memo[n][l][r];
        int half = (n + 1) / 2;
        int mn = Integer.MAX_VALUE, mx = Integer.MIN_VALUE;
        if (r <= n / 2) {
            for (int i = 0; i < l; i++) {
                for (int j = 0; j < r - l; j++) {
                    int[] res = dp(half, i + 1, i + j + 2);
                    mn = Math.min(mn, res[0] + 1);
                    mx = Math.max(mx, res[1] + 1);
                }
            }
        } else {
            int m = n + 1 - r;
            int fixed = (r - m) / 2;
            for (int i = 0; i < l; i++) {
                for (int j = 0; j < m - l; j++) {
                    int[] res = dp(half, i + 1, i + 1 + j + fixed + 1);
                    mn = Math.min(mn, res[0] + 1);
                    mx = Math.max(mx, res[1] + 1);
                }
            }
        }
        memo[n][l][r] = new int[]{mn, mx};
        return memo[n][l][r];
    }
}
