```java
class Solution {
    public boolean validateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] indeg = new int[n];
        for (int i = 0; i < n; i++) {
            if (leftChild[i] != -1) {
                if (++indeg[leftChild[i]] > 1) return false;
            }
            if (rightChild[i] != -1) {
                if (++indeg[rightChild[i]] > 1) return false;
            }
        }
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (indeg[i] == 0) {
                if (root != -1) return false;
                root = i;
            }
        }
        if (root == -1) return false;
        boolean[] visited = new boolean[n];
        int[] stack = new int[n];
        int top = 0;
        stack[top++] = root;
        visited[root] = true;
        int count = 0;
        while (top > 0) {
            int node = stack[--top];
            count++;
            int l = leftChild[node], r = rightChild[node];
            if (l != -1) {
                if (visited[l]) return false;
                visited[l] = true;
                stack[top++] = l;
            }
            if (r != -1) {
                if (visited[r]) return false;
                visited[r] = true;
                stack[top++] = r;
            }
        }
        return count == n;
    }
}
